import React, { Component } from "react";
import avatar from "../assets/images/header/Hamid.png";
import { calculateBannerHeight } from "../utils/bannerHeight";

class Header extends Component {
    titles = [];

    constructor() {
        super();
        this.state = { checked: false, windowInnerHeight: window.innerHeight, bannerSize: 300, mobileVersion: false };
        this.onThemeSwitchChange = this.onThemeSwitchChange.bind(this);
    }

    componentDidMount() {
        this.updateLayout(window.innerHeight, window.innerWidth);
        window.addEventListener("orientationchange", this.onOrientationChange);
    }

    componentWillUnmount() {
        window.removeEventListener("orientationchange", this.onOrientationChange);
    }

    // Dimensions are still pre-rotation when this fires, so they are passed swapped.
    onOrientationChange = () => {
        this.updateLayout(window.innerWidth, window.innerHeight);
    };

    updateLayout(height, width) {
        var bannerHeight = calculateBannerHeight(height, width);
        var mobileVersion = (bannerHeight <= 300 && width < 1500) || ((width < (height + 100) * 3 / 4) && width < 1500);
        this.setState({windowInnerHeight: height, bannerSize: bannerHeight, mobileVersion});
    }

    onThemeSwitchChange(checked) {
        this.setState({checked});
        this.setTheme();
    }


    setTheme() {
        var dataThemeAttribute = "data-theme";
        var body = document.body;
        var newTheme =
            body.getAttribute(dataThemeAttribute) === "dark" ? "light" : "dark";
        body.setAttribute(dataThemeAttribute, newTheme);
    }

    render() {
        if (this.props.sharedData) {
            var name = this.props.sharedData.name;
            this.titles = this.props.sharedData.titles.map(x => [ x.toUpperCase(), 1500 ] ).flat();
        }

        // const HeaderTitleTypeAnimation = React.memo( () => {
        //     return <Typical className="title-styles" steps={this.titles} loop={50} />
        // }, (props, prevProp) => true);

        return (
            <div
                id="home"
                className="container"
                style={{
                    height: this.state.mobileVersion ? this.state.windowInnerHeight - this.state.bannerSize + 100 :
                        this.state.windowInnerHeight - this.state.bannerSize,
                    width: '100%',
                    position: 'relative',
                    flexDirection: 'column',
                    justifyContent: "center",
                    alignItems: 'center',
                }}
            >
                {!this.state.mobileVersion && <div>
                    <h1 style={{ color: "#f4f4f4", margin: '0 auto', marginTop: 10, fontSize: '350%', textAlign: 'center' }}>
                        <span>About me</span>
                    </h1>
                    <div
                        style={{
                            width: '200px',
                            height: '4px',
                            borderRadius: 3,
                            backgroundColor: '#f4f4f4',
                            margin: '0 auto',
                            marginBottom: 40
                        }}
                    />
                </div>}
                <div className= "row">
                    <div
                        className= "col-xl-4"
                        style={{ marginTop: this.state.mobileVersion ? -70 : 0, }}
                    >
                        <img
                            src={avatar}
                            style={{
                                width: this.state.mobileVersion ? 140 : 200,
                                height: this.state.mobileVersion ? 140 : 200,
                                borderRadius: '50%',
                                display: 'block',
                                marginLeft: 'auto',
                                marginRight: 'auto',
                                marginBottom: 10,
                            }}
                        />
                        <h1 style={{ color: "#f4f4f4", marginBottom: 7, textAlign: 'center' }}>
                            <span style={{ fontSize: '4.0vh' }}>Hamid (Rennd) Bashiri</span>
                        </h1>
                        <h1 style={{ color: "#f4f4f4", fontSize: '4vh', textAlign: 'center'}}>
                            <a style={{ color: "#f4f4f4", textDecoration: "none"}} href={"mailto:hvbashiri@gmail.com"}>
                                <span style={{ margin: 7 }} className="iconify" data-icon="mdi:email" />
                            </a>
                            <a style={{ color: "#f4f4f4", textDecoration: "none"}} href={"https://www.linkedin.com/in/hbashiri/"}>
                                <span style={{ margin: 7 }} className="iconify" data-icon="mdi:linkedin" />
                            </a>
                            <a style={{ color: "#f4f4f4", textDecoration: "none"}} href={"https://www.instagram.com/h__bashiri/"}>
                                <span style={{ margin: 7 }} className="iconify" data-icon="mdi:instagram" />
                            </a>
                            <a style={{ color: "#f4f4f4", textDecoration: "none"}} href={"https://medium.com/@hvbashiri"}>
                                <span style={{ margin: 7 }} className="iconify" data-icon="mdi:alpha-m-box" />
                            </a>
                        </h1>
                    </div>
                    <div
                        className="col-xl-8"
                        style={{display: 'flex', alignItems: 'center'}}
                    >
                        <h3
                            style={{
                                color: "#f4f4f4",
                                marginBottom: 20,
                                textAlign: 'justify',
                                textAlignLast: 'center',
                                maxWidth: "100%",
                                marginLeft: 10,
                                marginRight: 10,
                            }}
                        >
            <span style={{ fontSize: '2.3vh' }}>
                Passionate  game developer with 5 years of experience focused on PC games using Unity engine and C#. I excel in various aspects of game development, including designing project architecture, developing AI systems, creating tools and implementing gameplay features. With an additional 2 years of experience in software engineering and an MSc degree in software engineering, I have a solid educational background that complements my practical experience.
                Have a look at my technical articles in <a style={{color: "#F4A261"}} href={"https://medium.com/@hvbashiri"}>Medium</a>.
            </span>
                        </h3>
                    </div>
                </div>
            </div>
        );
    }
}

export default Header;